import * as React from "react"

import { cn } from "@/lib/utils"

type SelectProps = React.ComponentProps<"select"> & {
  /** The words before the choice: "Sort by". Clicking them opens the list. */
  label?: React.ReactNode
  /** Classes for the sentence around the choice. className goes to the select. */
  rootClassName?: string
  /** Pins a state for documentation ("hover"); set on the root. */
  "data-force"?: string
}

/** A choice inside a sentence. The chosen word is yours, in italic over a hairline. Give it <option>s. */
function Select({ label, className, rootClassName, "data-force": force, children, ...props }: SelectProps) {
  const Root = label ? "label" : "span"
  return (
    <Root data-slot="select" data-force={force} className={cn("db-select", rootClassName)}>
      {label ? <span>{label}</span> : null}
      <span className="db-select-box">
        <select data-slot="select-input" className={className} {...props}>
          {children}
        </select>
      </span>
    </Root>
  )
}

export { Select, type SelectProps }

@layer components {
  /* ── db-select ── a choice inside a sentence */
  .db-select { display: inline-flex; flex-wrap: wrap; align-items: baseline; column-gap: 0.25em; font-size: var(--db-mp); line-height: var(--db-mp-lh); color: var(--db-graphite); }
  .db-select-box { position: relative; display: inline-flex; align-items: baseline; }
  .db-select-box::after {
    content: "↓" / ""; position: absolute; inset-inline-end: 0; bottom: 0.3em;
    font-family: var(--db-voice); font-size: 0.72em; line-height: 1; color: var(--db-pencil); pointer-events: none;
    transition: translate var(--db-moderato) var(--db-exhale), color var(--db-allegro);
  }
  :is(.db-select-box:hover, .db-select[data-force~="hover"] .db-select-box)::after { translate: 0 2px; color: var(--db-ink); }
  .db-select select {
    -webkit-appearance: none; appearance: none; field-sizing: content;
    margin: 0; border: 0; border-radius: 0; padding: 0 0.6em 0.1em 0; /* the arrow sits in the padding */
    background: linear-gradient(var(--db-rule-strong), var(--db-rule-strong)) no-repeat 0 100% / calc(100% - 0.6em) var(--db-hairline);
    color: var(--db-ink); cursor: pointer;
    font-family: var(--db-expression); font-style: italic; font-weight: 400;
    font-size: calc(var(--db-expression-scale) * 1em); line-height: 1.2;
  }
  .db-select select:is([dir="rtl"], [dir="rtl"] *) { padding: 0 0 0.1em 0.6em; background-position: 100% 100%; }
  .db-select select:focus-visible { outline-offset: 4px; }
  .db-select select:disabled { color: var(--db-pencil); cursor: not-allowed; }
  @supports (appearance: base-select) {
    .db-select select, .db-select select::picker(select) { appearance: base-select; }
    .db-select select { display: inline-flex; min-block-size: 0; }
    .db-select select::picker-icon { display: none; }
    .db-select select::picker(select) {
      margin-top: var(--db-space-2); padding: var(--db-space-2) 0; border: 0;
      background: var(--db-paper); box-shadow: inset 0 0 0 var(--db-hairline) var(--db-rule);
      color: var(--db-graphite); scrollbar-width: none; /* the picker is the browser's own: it takes no rail, and only a very long list scrolls */
    }
    .db-select option { padding: 0.3em 1.1em; }
    .db-select option::checkmark { display: none; }
    .db-select option { position: relative; padding-inline-start: 1.6em; }
    .db-select option:checked { color: var(--db-ink); }
    .db-select option:checked::before { content: ""; position: absolute; inset-inline-start: 0.7em; top: calc(50% - 3px); width: 6px; height: 6px; border-radius: 50%; background: var(--db-accent); }
    .db-select option:is(:hover, :focus-visible) { background: var(--db-mark); color: var(--db-on-mark); outline: 0; }
    .db-select select::picker(select) { transition: opacity var(--db-moderato) var(--db-exhale), translate var(--db-moderato) var(--db-exhale), overlay var(--db-moderato) allow-discrete, display var(--db-moderato) allow-discrete; }
    @starting-style { .db-select select:open::picker(select) { opacity: 0; translate: 0 -6px; } }
    .db-select select:open option { animation: db-arrive var(--db-moderato) var(--db-exhale) backwards; animation-delay: calc((sibling-index() - 1) * var(--db-arpeggio)); }
  }
}
